    getFile: {
        parameters: {
            query?: never;
            header?: {
                /** @description A byte range. A stored file honours several ranges (multipart/byteranges); a partial file from TDLib's cache answers at most the bytes it holds from the first range's start. */
                Range?: string;
                "If-Range"?: string;
                "If-Modified-Since"?: string;
            };
            path: {
                /** @description The file token, as minted into the pages and the API. */
                token: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The whole file. */
            200: {
                headers: {
                    "Accept-Ranges": components["headers"]["AcceptRanges"];
                    "Cache-Control": components["headers"]["FileCacheControl"];
                    "Content-Disposition": components["headers"]["ContentDisposition"];
                    /** @description For a stored file. */
                    "Last-Modified"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/octet-stream": string;
                };
            };
            /** @description The requested range, or for a file still being fetched the part of it already there; Content-Range carries the file's full size. */
            206: {
                headers: {
                    "Accept-Ranges": components["headers"]["AcceptRanges"];
                    "Cache-Control": components["headers"]["FileCacheControl"];
                    "Content-Disposition": components["headers"]["ContentDisposition"];
                    "Content-Range"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/octet-stream": string;
                    "multipart/byteranges": string;
                };
            };
            /** @description Not modified since If-Modified-Since (a stored file). */
            304: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Not in the store and too big to fetch without a session ("Sign in to load this file"). */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
            /** @description No such file, a token that does not open, or not in the store while fetching from Telegram is not configured or the signed-in account may not fetch files (fetch_files). */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
            /** @description The file is no longer available on Telegram. */
            410: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
            /** @description The range is outside the file. */
            416: {
                headers: {
                    /** @description bytes *\/<size>, when the size is known. */
                    "Content-Range"?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The file could not be served. */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
            /** @description The daemon answered something unexpected. */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
            /** @description The daemon is busy, unreachable or not signed in to Telegram, or the file moved while it was being opened; try again after Retry-After seconds. */
            503: {
                headers: {
                    /** @description Seconds to wait before asking again. */
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
            /** @description Telegram took too long; the fetch goes on in the background. */
            504: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
        };
    };
